validator.javascript:

		function removeCommas (value){

		var nonCommasValue = "";
		var prevPos = 0;
		var curPos = value.indexOf(",");

		if (curPos == -1)
			return value;


		while (curPos != -1) {
			nonCommasValue += value.substring(prevPos, curPos);
			prevPos = curPos +1;
			curPos = value.indexOf(",", prevPos);
		}
		nonCommasValue += value.substring(prevPos);
		return nonCommasValue;
        }



			function jTrim(theString){
				while(theString.indexOf(' ')==0 && theString.length>0)
					theString = theString.substr(1);
				while(theString.lastIndexOf(' ')==theString.length-1 && theString.length>0)
					theString = theString.substr(0,(theString.length-1));
				return theString;
		}         

            function validateRequired(form) {
                var bValid = true;
                var focusField = null;
                var i = 0;
                var fields = new Array();
                oRequired = eval("new " +form.name+ "Required (form)");

                for (x in oRequired) {
                    if ((form[oRequired[x][0]]) && ((form[oRequired[x][0]].type == 'text' || form[oRequired[x][0]].type == 'textarea' || form[oRequired[x][0]].type == 'select-one' || form[oRequired[x][0]].type == 'radio' || form[oRequired[x][0]].type == 'password') && 
jTrim(form[oRequired[x][0]].value) == '')){
                       if (i == 0)
                          focusField = form[oRequired[x][0]];

                       fields[i++] = oRequired[x][1];

                       bValid = false;
                    }
                }

                if (fields.length > 0) {
                   try{
                   focusField.focus();
                   }catch(e){}
                   alert(fields.join('\n'));
                }

                return bValid;
            }

function validateMinLength(form) {
    var bValid = true;
    var focusField = null;
    var i = 0;
    var fields = new Array();
    oMinLength = eval("new " +form.name+ "Minlength (form)");

    for (x in oMinLength) {
        if ((form[oMinLength[x][0]]) && (form[oMinLength[x][0]].type == 'text' || form[oMinLength[x][0]].type == 'textarea') && form[oMinLength[x][0]].value.length > 0) {
           var iMin = parseInt(oMinLength[x][2]("minlength"));

           if (!(form[oMinLength[x][0]].value.length >= iMin)) {
              if (i == 0)
                 focusField = form[oMinLength[x][0]];

              fields[i++] = oMinLength[x][1];

              bValid = false;
           }
        }
    }

    if (fields.length > 0) {
       focusField.focus();
       alert(fields.join('\n'));
    }

    return bValid;
}

