function validateMask(form) {
    var bValid = true;
    var focusField = null;
    var i = 0;
    var fields = new Array();
    oMasked = eval("new " +form.name+ "Mask(form)");

    for (x in oMasked) {
        if ((form[oMasked[x][0]]) && ((form[oMasked[x][0]].type == 'text' || form[oMasked[x][0]].type == 'textarea' || form[oMasked[x][0]].type == 'password') && form[oMasked[x][0]].value.length > 0)) {
           if (!matchPattern(form[oMasked[x][0]].value, oMasked[x][2]("mask"))) {
              if (i == 0)
                 focusField = form[oMasked[x][0]];

              fields[i++] = oMasked[x][1];
              bValid = false;
           }
        }
    }

    if (fields.length > 0) {
       focusField.focus();
       alert(fields.join('\n'));
    }

    return bValid;
}

function matchPattern(value, mask) {
   var bMatched = mask.exec(value);

   if(!bMatched) {
      return false;
   }

   return true;
}

