function validateShort(form) {
    var bValid = true;
    var focusField = null;
    var i = 0;
    var fields = new Array();
    oShort = eval("new " +form.name+ "ShortValidations(form)");

    for (x in oShort) {
        if ((form[oShort[x][0]]) && ((form[oShort[x][0]].type == 'text' || form[oShort[x][0]].type == 'textarea' || form[oShort[x][0]].type == 'select-one' || form[oShort[x][0]].type == 'radio') && form[oShort[x][0]].value.length > 0)) {
           var foundError = (!matchShortPattern(form[oShort[x][0]].value));
           if (!foundError){
           	   var iValue = parseInt(removeCommas(form[oShort[x][0]].value));
               foundError = (!(iValue >= -32768 && iValue <= 32767));
           }

           if (foundError){
              if (i == 0)
                 focusField = form[oShort[x][0]];

              fields[i++] = oShort[x][1];

              bValid = false;
           }
        }
    }

    if (fields.length > 0) {
       focusField.focus();
       alert(fields.join('\n'));
    }

    return bValid;
}

function matchShortPattern(value) {
   var shortMask = new RegExp("^([0-9]*|[0-9]{1,3}(,[0-9]{3})*)$");
   return shortMask.exec(value);
}

