function matchIntegerPattern(value) {
   var integerMask = new RegExp("^([0-9]*|[0-9]{1,3}(,[0-9]{3})*)$");
   return integerMask.exec(value);
}

            function validateLong(form) {
                var bValid = true;
                var focusField = null;
                var i = 0;
                var fields = new Array();
