                       var foundError = (!matchLongPattern(form[oLong[x][0]].value));

                       if (!foundError){
	                  var iValue = new Number(removeCommas(form[oLong[x][0]].value));
	                  var maxLongValue = new Number(9223372036854775000);
	                  var minLongValue = new Number(-9223372036854775000);

                          foundError = (!(iValue.valueOf() >= minLongValue.valueOf() && iValue.valueOf() <= maxLongValue.valueOf()))
                       }

                       if (foundError){

                            if (i == 0)
                               focusField = form[oLong[x][0]];

                            fields[i++] = oLong[x][1];

                            bValid = false;
                       }
                    }
                }

                if (fields.length > 0) {
                   focusField.focus();
                   alert(fields.join('\n'));
                }

                return bValid;
            }

            function matchLongPattern(value) {
               var longMask = new RegExp("^([0-9]*|[0-9]{1,3}(,[0-9]{3})*)$");
               return longMask.exec(value);
            }

