               dateRegexp = new RegExp("^(\\d{4})[" + delim1 + "](\\d{2})[" + delim2 + "](\\d{2})$");
            }

            var matched = dateRegexp.exec(value);

            if(matched != null) {

               if (!isInRange(matched[1], minYear, maxYear)) {
                  if (i == 0)
                     focusField = form[oDate[x][0]];

