   }

   return bValid;
}

function isInRange(value, minValue, maxValue) {
	return (value >= minValue && value <= maxValue);
}

function validateRange(form) {
    var bValid = true;
    var focusField = null;
    var i = 0;
    var fields = new Array();
    oRange = eval("new " +form.name+ "Range(form)");

    for (x in oRange) {
        if ((form[oRange[x][0]]) && ((form[oRange[x][0]].type == 'text' || form[oRange[x][0]].type == 'textarea') && form[oRange[x][0]].value.length > 0)) {
           var iMin = parseInt(oRange[x][2]("min"));
           var iMax = parseInt(oRange[x][2]("max"));
           var iValue = removeCommas(form[oRange[x][0]].value);

           if (!(iValue >= iMin && iValue <= iMax)) {
              if (i == 0)
                 focusField = form[oRange[x][0]];

              fields[i++] = oRange[x][1];

              bValid = false;
           }
        }
    }

    if (fields.length > 0) {
       focusField.focus();
       alert(fields.join('\n'));
    }

    return bValid;
}

function validateCreditCard(form) {
    var bValid = true;
